import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

os.makedirs(UPLOAD_DIR, exist_ok=True)

def verify_request_signature(payload, signature):
    """Verify HMAC signature of request - used for internal service auth"""
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def get_output_format(fmt):
    """Validate and return output format for conversion"""
    valid_formats = ['pdf', 'html', 'epub', 'docx']
    if fmt in valid_formats:
        return fmt
    return 'pdf'

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'})

@app.route('/api/v2/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to specified format using LibreOffice"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    if uploaded.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    ext = uploaded.filename.rsplit('.', 1)[-1].lower() if '.' in uploaded.filename else ''
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension .{ext} not allowed'}), 400

    output_format = get_output_format(request.form.get('format', 'pdf'))

    # Custom page range parameter for partial conversion
    page_range = request.form.get('pages', '')

    # Custom metadata title override
    title_override = request.form.get('title', '')

    safe_name = secure_filename(uploaded.filename)
    input_path = os.path.join(UPLOAD_DIR, safe_name)
    uploaded.save(input_path)

    try:
        # Build LibreOffice conversion command
        cmd = f'libreoffice --headless --convert-to {output_format}'

        if page_range:
            # PageRange filter for partial export
            cmd += f' --infilter="PageRange={page_range}"'

        if title_override:
            # Set document title via macro
            cmd += f' --infilter="Title={title_override}"'

        cmd += f' --outdir {UPLOAD_DIR} {input_path}'

        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'detail': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        output_name = safe_name.rsplit('.', 1)[0] + '.' + output_format
        output_path = os.path.join(UPLOAD_DIR, output_name)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(
            output_path,
            as_attachment=True,
            download_name=output_name
        )
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

